// caesar_medium: experiments/psi/caesar_medium.psi of Tractables/Alea.jl, branch arithmetic,
// commit 7e9ff23517086eb4518845e50218bf18b4d9f2a5 (Apache License 2.0), the
// Psi program of Cao et al. (UAI 2023); this header added.
def draw(key, obs) { 
    drawnChar := categorical([0.082, 0.018, 0.024, 0.04, 0.123, 0.022, 0.022, 0.066, 0.069, 0.001, 0.008, 0.045, 0.024, 0.069, 0.073, 0.018, 0.002, 0.055, 0.067, 0.092, 0.028, 0.009, 0.023, 0.001, 0.018, 0.001]);
    encrypted := drawnChar + key;
    if (encrypted > 25) {
        encrypted = encrypted - 26;
    }
    observe(encrypted == obs);
    return 0;
}
def main(){
    key := uniformInt(0, 25);
    text := [9, 11, 8, 21, 20, 21, 2, 5, 2, 12, 13, 2, 22, 9, 11, 8, 0, 11, 20, 6, 6, 2, 7, 0, 5, 20, 7, 0, 14, 20, 0, 24, 12, 9, 9, 5, 12, 20, 11, 24, 20, 7, 24, 17, 9, 11, 24, 12, 12, 2];
    for i in [0..text.length) {
        draw(key, text[i]);
    }
    return key;
}

